import { expect, test } from '@playwright/test';

// The manifest is generated by the production build, so these checks use the
// preview server rather than the dev server.
test('the production build publishes a complete web app manifest', async ({ page }) => {
  await page.goto('http://localhost:4174/');

  await expect(page.locator('link[rel="manifest"]')).toHaveAttribute(
    'href',
    /manifest\.webmanifest$/
  );

  const manifest = await (await page.request.get('http://localhost:4174/manifest.webmanifest')).json();
  expect(manifest.name).toBe('vacasky - Tours & Travel');
  expect(manifest.short_name).toBe('vacasky');
  expect(manifest.start_url).toBe('/');
  expect(manifest.scope).toBe('/');
  expect(manifest.display).toBe('standalone');
  expect(manifest.theme_color.toLowerCase()).toBe('#2c7ba8');
  expect(manifest.icons).toHaveLength(3);
  expect(manifest.icons.some((icon) => icon.sizes === '192x192')).toBe(true);
  expect(manifest.icons.some((icon) => icon.sizes === '512x512')).toBe(true);
  expect(manifest.icons.some((icon) => icon.purpose === 'maskable')).toBe(true);
});

// Uses the production build served by `vite preview`, because the service
// worker is only registered there.
test('offline navigation falls back to the offline page', async ({ page, context }, testInfo) => {
  await page.goto('http://localhost:4174/');
  await page.evaluate(() => navigator.serviceWorker.ready);
  await page.reload();
  await page.waitForFunction(() => Boolean(navigator.serviceWorker.controller));

  await context.setOffline(true);
  await page.goto('http://localhost:4174/tours/komodo-sailing-3d2n').catch(() => {});

  // NetworkFirst waits 3s for the network before serving the fallback.
  await expect(page.getByRole('heading', { name: "You're offline" })).toBeVisible({
    timeout: 15000,
  });
  await expect(page.getByRole('button', { name: 'Try again' })).toBeVisible();

  await page.screenshot({
    path: `docs/FEAT-001/evidence/offline-sw-${testInfo.project.name}.png`,
    fullPage: false,
  });

  await context.setOffline(false);
});
